<?php get_header(); ?><main id="main" class="container page-main"><header class="page-heading"><p class="eyebrow">THE JOURNAL</p><h1><?php if (is_search()) printf(esc_html__('Search results for: %s','digicarts'),esc_html(get_search_query())); elseif (is_archive()) the_archive_title(); else echo esc_html__('Ideas worth exploring.','digicarts'); ?></h1></header><?php if (have_posts()) : ?><div class="journal-grid"><?php while (have_posts()) : the_post(); ?><article <?php post_class('journal-card'); ?>><?php if (has_post_thumbnail()) : ?><a href="<?php the_permalink(); ?>"><?php the_post_thumbnail('large'); ?></a><?php endif; ?><p class="eyebrow"><?php echo esc_html(get_the_date()); ?></p><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?><a class="underlined-link" href="<?php the_permalink(); ?>">Read more <?php echo dc_icon('arrow'); ?></a></article><?php endwhile; ?></div><?php the_posts_pagination(); else : ?><p>No results yet. Try a different search.</p><?php get_search_form(); endif; ?></main><?php get_footer(); ?>
